ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	method : Mule::p('cie.referrals.method'),
	host: Mule::p('cie.host'),
	port: Mule::p('cie.port'),
	path : Mule::p('cie.referrals.path'),
	params: {
		lastModifiedDate: vars.lastModifiedDate
	}
}

ee:message.ee:set-payload:
%dw 2.0 output application/json var payload = vars.cieReferral --- { // External ID / Core Identifiers CIE_Referral_ID__c: payload.referral_id, ClientId: payload.account_id, // Maps to the Lookup(Account) field
// Status and Dates CIE_Referral_Status__c: payload.referral_status, ReferralDate: payload.referral_date as Date {format: "yyyy-MM-dd"} default null, CIE_Accepted_Date_PLI__c: payload.accepted_date as Date {format: "yyyy-MM-dd"} default null, CIE_Declined_Date_PLI__c: payload.declined_date as Date {format: "yyyy-MM-dd"} default null, CIE_Date_of_referral_outcome_PLI__c: payload.completed_date as Date {format: "yyyy-MM-dd"} default null, CIE_Program_Entry_Date_PLI__c: payload.enrollment_entry_date as Date {format: "yyyy-MM-dd"} default null,
// Referral Details CIE_Domain_Name_PLI__c: payload.domain_name, CIE_Referral_Method_PLI__c: payload.referral_method, CIE_Appropriateness_of_Referral_PLI__c: payload.appropriateness_referral, CIE_Appropriateness_of_Referral_Note_PLI__c: payload.appropriateness_referral_notes,
// Outcomes and Notes CIE_Referral_Outcome_PLI__c: payload.outcome, CIE_Referral_Outcome_Note_PLI__c: payload.outcome_notes, CIE_Reason_Client_was_not_Connected_PLI__c: payload.reason_not_connected, CIE_Agent_Note_PLI__c: payload.agent_notes, CS_Referral_Notes__c: payload.referral_notes,
// Provider / Agency mapping (using standard text fields for the agency info) ProviderOrg: payload.agency_name,
// Consolidating additional context into the Description field Description: "Service Name: " ++ (payload.service_name default "") ++ "\nZ-Code: " ++ (payload.z_code_name default "") ++ "\nTaxonomies: " ++ ((payload.referral_taxonomies.taxonomy_name default []) joinBy ", ") }
